import type { ImgHTMLAttributes } from "react";
import { cn } from "@/lib/utils";

/**
 * MeterPal brand marks, loaded from the canonical assets in assets/images/.
 * Every file below is generated by scripts/sync-brand-assets.mjs — never
 * hand-edited at these public paths.
 *
 *   MeterPalWordmark  /meterpal-logo-color.svg  <- logo.svg       (light surfaces)
 *                     /meterpal-logo-white.svg  <- logo-white.svg (dark surfaces)
 *   MeterPalMark      /meterpal-icon.svg        <- icon.svg       (light surfaces)
 *                     /meterpal-icon-white.svg  <- icon-white.svg (dark surfaces)
 *
 * `variant` forces a treatment for a surface whose colour is known (the auth
 * hero panel is always dark). "auto" follows the app's .dark theme class.
 */
type BrandVariant = "auto" | "light" | "dark";

type BrandProps = ImgHTMLAttributes<HTMLImageElement> & {
	variant?: BrandVariant;
};

type BrandAsset = { light: string; dark: string };

const WORDMARK: BrandAsset = {
	light: "/meterpal-logo-color.svg",
	dark: "/meterpal-logo-white.svg",
};

const MARK: BrandAsset = {
	light: "/meterpal-icon.svg",
	dark: "/meterpal-icon-white.svg",
};

function BrandImg({
	asset,
	variant = "auto",
	className,
	alt = "MeterPal",
	...props
}: BrandProps & { asset: BrandAsset }) {
	if (variant !== "auto") {
		return (
			<img
				src={variant === "dark" ? asset.dark : asset.light}
				alt={alt}
				className={className}
				{...props}
			/>
		);
	}

	// Both files render; the theme class decides which one is in the box. The
	// hidden copy is display:none, so it never adds height or reaches the a11y
	// tree twice.
	return (
		<>
			<img
				src={asset.light}
				alt={alt}
				className={cn(className, "dark:hidden")}
				{...props}
			/>
			<img
				src={asset.dark}
				alt={alt}
				className={cn(className, "hidden dark:block")}
				{...props}
			/>
		</>
	);
}

export function MeterPalWordmark(props: BrandProps) {
	return <BrandImg asset={WORDMARK} {...props} />;
}

/** The square mark on its own, for rails too narrow for the wordmark. */
export function MeterPalMark(props: BrandProps) {
	return <BrandImg asset={MARK} {...props} />;
}
